def sort_mixed_list(mixed_list: list[Union[int, str]]) -> list[Union[int, str]]:
    """
    Sort a mixed list of integers and strings.
    Integers are sorted numerically and placed before strings, which are
    sorted alphabetically.
    """
    if not isinstance(mixed_list, list):
        raise TypeError(f"Expected a list, but received {type(mixed_list).__name__}")
    if not all(isinstance(x, (int, str)) for x in mixed_list):
        raise TypeError("The list must contain only integers and strings.")
    return sorted(mixed_list, key=lambda x: (0 if isinstance(x, int) else 1, x))

